ruleContent.content:
@js:
var d = JSON.parse(result);
var imgs = d.data.images;
var html = '';
if (imgs) {
  for (var i = 0; i < imgs.length; i++) {
    html += '<img src="' + imgs[i].url + '">\n';
  }
}
html

ruleContent.nextContentUrl:
@js:
var d = JSON.parse(result);
var p = d.data && d.data.pagination;
if (p && p.current_page < p.total_pages) {
  baseUrl.replace('page=' + p.current_page, 'page=' + (p.current_page + 1));
}
